async function supaFetch(path, options = {}) {
  const res = await fetch(`${SUPA_URL}/rest/v1/${path}`, {
    headers: {
      "apikey": SUPA_KEY,
      "Authorization": `Bearer ${SUPA_KEY}`,
      "Content-Type": "application/json",
      "Prefer": options.prefer || "return=representation",
      ...options.headers,
    },
    ...options,
  });
  if (!res.ok) {
    const err = await res.text();
    throw new Error(`Supabase error ${res.status}: ${err}`);
  }
  const text = await res.text();
  return text ? JSON.parse(text) : null;
}

// CRUD helpers
// Nome de exibição: apelido se existir, senão nome completo
function nomeExibicao(atleta) {
  if (!atleta) return "?";
  return atleta.apelido ? atleta.apelido : atleta.name;
}
// Um atleta só entra no RANKING (não confundir com "estar no circuito") quando,
// além de estar ativo e fora do backlog (pendenteCircuito:false), já JOGOU pelo
// menos uma partida cujo resultado foi PROCESSADO (calculado) na temporada.
// `pendenteCircuito:false` sozinho só diz que ele PODE ser pareado; ter partida
// ATRIBUÍDA (só pareado) também não basta — senão quem entra no meio da temporada
// aparece na frente de quem já jogou, ainda com 0 pts. Ele entra no ranking na
// hora em que o admin atualiza o ranking (processa a rodada da 1ª partida dele).
function estaNoRanking(atleta, matches) {
  if (!atleta || atleta.status !== "ativo" || atleta.pendenteCircuito) return false;
  return matches.some(m => (m.p1Id === atleta.id || m.p2Id === atleta.id) && m.calculado && !m.rejeitado);
}
// Nome com apelido entre parênteses (para telas administrativas)
function nomeComApelido(atleta) {
  if (!atleta) return "?";
  return atleta.apelido ? `${atleta.name} (${atleta.apelido})` : atleta.name;
}
// "mês/ano" de ingresso, calculado a partir da data de inscrição já existente —
// usado na carta colecionável ("Membro desde"), sem precisar de um campo novo.
const MESES_ABREV = ["jan","fev","mar","abr","mai","jun","jul","ago","set","out","nov","dez"];
const MESES_NOME = ["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
function membroDesde(inscritoEm) {
  if (!inscritoEm) return "";
  const d = new Date(inscritoEm);
  if (isNaN(d.getTime())) return "";
  return `${MESES_ABREV[d.getMonth()]}/${d.getFullYear()}`;
}
// Nome do mês (por extenso) a partir do prazo da rodada ("YYYY-MM-DD"). Como o
// prazo já reflete o mês real do par (jul, ago...), a mensagem mostra o mês certo
// mesmo que o admin envie a programação do mês seguinte com antecedência.
function mesDoPrazo(deadline) {
  if (!deadline) return "";
  const d = new Date((typeof deadline === "string" && deadline.length === 10) ? deadline + "T12:00:00" : deadline);
  if (isNaN(d.getTime())) return "";
  return MESES_NOME[d.getMonth()];
}

